from typing import List

def rolling_max(numbers: List[int]) -> List[int]:
    max_so_far = numbers[0]
    result = [0] * len(numbers)

    for i in range(len(numbers)):
        if numbers[i] > max_so_far:
            max_so_far = numbers[i]
        result[i] = max_so_far

    return result

