method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0
    ensures |result| == |numbers|
    ensures forall i: int :: 0 <= i < |result| ==> result[i] == Max(numbers[0..i+1])
{
    var maxSoFar := numbers[0];
    var n := |numbers|;
    var res := new int[n];

    // Fill the result array with rolling maximums
    var i := 0;
    while i < n
        invariant 0 <= i <= n
        invariant forall j: int :: 0 <= j < i ==> res[j] == Max(numbers[0..j+1])
    {
        if numbers[i] > maxSoFar {
            maxSoFar := numbers[i];
        }
        res[i] := maxSoFar;
        i := i + 1;
    }

    result := res;
}

